"use strict";
const vue = require("vue");
let globalId = 0;
const _sfc_main = vue.defineComponent({
  name: "OIconSuccess",
  svgType: "color",
  setup() {
    const classNames = ["o-svg-icon", "o-icon-success", "type-color"];
    const isClient = vue.ref(false);
    vue.onMounted(() => {
      isClient.value = true;
    });
    return {
      isClient,
      classNames,
      globalId: globalId++
    };
  }
});
module.exports = _sfc_main;
